                    ::oox::drawingml::LinePropertiesPtr pLineProperties = std::make_shared<oox::drawingml::LineProperties>();
                    rLineBorders[ mnLineType ] = pLineProperties;
                    return new LinePropertiesContext( *this, rAttribs, *pLineProperties );
